pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address account, bool access) public {
        // Precondition: avoid zero address (the contract's deployer is address(this) which is used as owner)
        vm.assume(account != address(0) && account != address(this));

        // Drive the contract: set admin access for account
        c.adjustAdminAccess(account, access);

        // General rule: after setting admin access, isApprovedForAll(account, account) equals the set access
        bool approved = c.isApprovedForAll(account, account);
        assertTrue(approved == access, "isApprovedForAll(account, account) should equal isAdmin[account]");
    }
}

