pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address caller, address admin, bool access, uint256 tokenId, address owner) public {
        // Ensure tokenId is within existing items — create one
        vm.assume(caller != address(0) && admin != address(0));
        vm.assume(tokenId < c.uniqueTokensOutstanding() || c.uniqueTokensOutstanding() == 0);
        if (c.uniqueTokensOutstanding() == 0) {
            // Create a minimal game item with dailyAllowance > 0
            vm.prank(address(this));
            c.createGameItem("test", "uri", false, true, 0, 0, 100);
        }
        tokenId = bound(tokenId, 0, c.uniqueTokensOutstanding() - 1);
        // Record allowanceRemaining before adjustAdminAccess
        uint256 before = c.getAllowanceRemaining(owner, tokenId);
        // Call adjustAdminAccess
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("adjustAdminAccess(address,bool)", admin, access));
        // The rule: if the call succeeded, allowanceRemaining must be unchanged.
        uint256 after = c.getAllowanceRemaining(owner, tokenId);
        assertTrue(!success || before == after);
    }
}

